CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenants(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE workspaces(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL);
CREATE TABLE memberships(user_id uuid NOT NULL REFERENCES users(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), role text NOT NULL CHECK(role IN ('owner','admin','editor','viewer')), PRIMARY KEY(user_id,workspace_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE assets(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), source_name text NOT NULL, object_key text UNIQUE NOT NULL, sha256 text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>0), mime text NOT NULL, report jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), asset_id uuid NOT NULL REFERENCES assets(id), name text NOT NULL, draft jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX projects_workspace ON projects(workspace_id, updated_at DESC);
CREATE TABLE project_versions(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), revision integer NOT NULL, draft jsonb NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,revision));
CREATE TABLE releases(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), asset_id uuid NOT NULL REFERENCES assets(id), version integer NOT NULL CHECK(version>0), manifest jsonb NOT NULL, manifest_hash text NOT NULL, published_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,version));
CREATE TABLE release_publications(release_id uuid PRIMARY KEY REFERENCES releases(id), active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE configurations(id uuid PRIMARY KEY, release_id uuid NOT NULL REFERENCES releases(id), user_id uuid REFERENCES users(id), state jsonb NOT NULL, price jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX configurations_release ON configurations(release_id);
CREATE TABLE audit_events(id uuid PRIMARY KEY, workspace_id uuid REFERENCES workspaces(id), user_id uuid REFERENCES users(id), action text NOT NULL, resource_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analytics_events(id uuid PRIMARY KEY, release_id uuid NOT NULL REFERENCES releases(id), event text NOT NULL CHECK(event IN ('view','configure','capture','export')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX analytics_release ON analytics_events(release_id,created_at);
CREATE FUNCTION prevent_release_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Releases are immutable'; END $$;
CREATE TRIGGER immutable_release BEFORE UPDATE OR DELETE ON releases FOR EACH ROW EXECUTE FUNCTION prevent_release_mutation();
INSERT INTO schema_migrations(version) VALUES('001_initial') ON CONFLICT DO NOTHING;
